; Proposals of worker bu: labels defined in my files that other modules use. OLD NEW ; SCOPE ; what
; --- ULTIMA (UDATA <-> INTRO) ---
L0000 PspInt20 ; ultima ; PSP:0000, the int 20h there: jumped to when BOOTUP.BIN cannot be opened (exit)
L005C PspFcb ; ultima ; PSP:005C, the default FCB used to open and read BOOTUP.BIN
L0068 FcbCurBlock ; ultima ; FCB+0Ch, current block (set 0)
L006A FcbRecSize ; ultima ; FCB+0Eh, record size (set to the file size: one read loads it all)
L006C FcbFileSize ; ultima ; FCB+10h, file size (low word)
L007C FcbCurRec ; ultima ; FCB+20h, current record (set 0)
L00FE ChainInt21 ; ultima ; PSP:00FE, where "int 21h" (CD 21) is planted before the chain load; runs into 0100
L0105 PartyLocation ; ultima ; 0105, the library's X01BE: set to 1 so KeyReady does not animate tiles
L4115 VideoSeg ; ultima ; dw 0B800h, the CGA segment the intro draws into
L5A2D DissolveRand ; ultima ; dw 9DE3h, pseudo-random state of CopyPicture's dissolve
L5A57 FileBootupBin ; ultima ; "BOOTUP.BIN"
L5CBA MsgNoGraphics ; ultima ; "Unable to access graphics display."
L5CE0 StartUp ; ultima ; INTRO's entry (from the jmp at 0100)
; --- BOOTUP (BDATA, TITLE, ORGANIZE, CREATE) ---
L005C PspFcb ; bootup ; PSP:005C, default FCB used to open and read EXODUS.BIN
L0068 FcbCurBlock ; bootup ; FCB+0Ch, current block (set 0)
L006A FcbRecSize ; bootup ; FCB+0Eh, record size (set to the file size)
L006C FcbFileSize ; bootup ; FCB+10h, file size (low word)
L007C FcbCurRec ; bootup ; FCB+20h, current record (set 0)
L00FA ChainInt21 ; bootup ; PSP:00FA, planted "int 21h" (CD 21) of the chain load
L00FC ChainJmp ; bootup ; PSP:00FC, planted FF 26 = "jmp word ptr [...]"
L00FE ChainJmpAddr ; bootup ; PSP:00FE, its operand 1328h: EXODUS's entry vector
L01B9 DiskCheckResult ; bootup ; 0FFh: "(Strange Disk)"; only set by the disabled AskScenarioDisk, so always 0
L01C3 PartySize ; bootup ; PARTY.ULT header +07: number of characters in the party (0-4)
L01C4 PartyX ; bootup ; header +08: start x (Form sets 2Ch)
L01C5 PartyY ; bootup ; header +09: start y (Form sets 14h)
L01C6 PartyRosterNums ; bootup ; header +0A-0D: roster numbers (1-20) of the party members (+0E-11 follow)
L01CE PartyChars ; bootup ; PARTY.ULT +12h: the four character records (100h bytes)
L0C46 FileExodusBin ; bootup ; "EXODUS.BIN"
L0CA9 MsgUltimaIII ; bootup ; 10h "Ultima III" 11h (10h/11h: bracket characters of CHARSET)
L0CB6 MsgPressSpace ; bootup ; 10h "Press <Space>" 11h
L0CC6 MsgCopyright ; bootup ; "(C)-1983 By James R. Van Artsdalen"
L0CE9 MsgLordBritish ; bootup ; "and Lord British"
L0CFA MsgEntry ; bootup ; "Entry#"
L0D01 MsgOnly1To20 ; bootup ; "(1-20 Only!)"
L0D0E MsgFromDepths ; bootup ; "From the depths of hell..."
L0D29 MsgVengeance ; bootup ; "...he comes for VENGEANCE!"
L0D5D StatusKeys ; bootup ; "GPDP" (sic, for GPDA): status letters of StatusNames; A is found as "not found" = the last
L0E2F MsgOptionSpace ; bootup ; "Option: " (main menu)
L0E38 MsgMenuReturn ; bootup ; "Return to the View"
L0E4B MsgMenuOrganize ; bootup ; "Organize a Party"
L0E5C MsgMenuJourney ; bootup ; "Journey Onward"
L0E83 MainMenuKeys ; bootup ; "ROJ",1Bh: keys of MainMenu
L0E8F MsgPartyOrganization ; bootup ; "Party Organization"
L0EA2 MsgOption ; bootup ; "Option:" (party menu)
L0EAA MsgMenuExamine ; bootup ; "Examine the Register"
L0EBF MsgMenuCreate ; bootup ; "Create a Character"
L0ED2 MsgMenuForm ; bootup ; "Form the Party"
L0EE1 MsgMenuDisperse ; bootup ; "Disperse the Party"
L0EF4 MsgMenuTerminate ; bootup ; "Terminate a Character"
L0F0A MsgMenuMain ; bootup ; "Main Menu"
L0F14 MsgMenuLook ; bootup ; "Look at a Character"
L0F59 OrganizeKeys ; bootup ; "ECFDTMQL",1Bh: keys of OrganizeMenu
L0F74 MsgRegister ; bootup ; "Register" (title of ExamineRegister)
