L1134 MsgDexterityColon ; bootup ; "Dexterity:"
L113F MsgIntelligenceColon ; bootup ; "Intelligence:"
L114D MsgWisdomColon ; bootup ; "Wisdom:"
L1155 MsgHitPointsColon ; bootup ; "Hit points:"
L1161 MsgExperienceColon ; bootup ; "Experience:"
L116D MsgFoodColon ; bootup ; "Food:"
L1173 MsgGoldColon ; bootup ; "Gold:"
L1179 MsgPlayerDash ; bootup ; "Player-"
L1181 MsgFormTitle ; bootup ; "Form the Party" (title of FormParty)
L1190 MsgPartyInUse ; bootup ; "(Party in Use)"
L119F MsgAlreadySelected ; bootup ; "Already Selected"
L11B0 MsgFormed ; bootup ; "(Formed)"
L11B9 MsgNoActivePlayers ; bootup ; "(No Active Players)"
L11CD MsgStrangeDisk ; bootup ; "(Strange Disk)"
